import subprocess, json; cmd = ['powershell', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', 'Get-CimInstance Win32_Service | Select-Object Name, DisplayName, PathName, StartMode | ConvertTo-Json -Compress']; print('👑 [SUPER-ROOT: TELEMETRÍA] Forzando volcado de memoria de servicios...'); out = subprocess.check_output(cmd, stderr=subprocess.DEVNULL).decode('cp1252').strip(); json.dump(json.loads(out), open('telemetria_credenciales.json', 'w', encoding='utf-8'), indent=4); print('[+] Base de datos de servicios consolidada.')
